"""Synthesize test-only `team` and `next` blocks (plan section A shape) from each
board's own fields. Output goes to scratchpad/site/audits. Never touches the repo."""
import json, glob, os, math, re, collections, datetime as dt, shutil

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "site", "audits-src")
OUT = os.path.join(HERE, "site", "audits")
GENERIC = {"src", "lib", "app", "core", "internal", "pkg", "main", "source", "packages", "crates", "docs", "content"}


def d(s):
    return dt.date.fromisoformat(s[:10])


def days(a, b):
    return (d(a) - d(b)).days


def ini(name):
    t = [x for x in re.split(r"[\s._-]+", name) if x]
    if len(t) >= 2:
        return (t[0][0] + t[1][0]).upper()
    return name[:2].upper()


def login_of(name):
    return name if re.fullmatch(r"[A-Za-z0-9-]{1,39}", name) and not re.fullmatch(r"[A-Z][a-z]+", name) else None


def frontier(file_w, T):
    """Plan B6 frontier split over a dict path->weight."""
    tree = collections.defaultdict(float)
    kids = collections.defaultdict(set)
    for p, w in file_w.items():
        parts = p.split("/")[:-1]
        for i in range(1, min(len(parts), 6) + 1):
            n = "/".join(parts[:i]) + "/"
            tree[n] += w
            par = "/".join(parts[:i - 1]) + "/" if i > 1 else ""
            kids[par].add(n)

    def descend(n):
        while True:
            c = [k for k in kids[n] if tree[k] >= 0.85 * tree[n]]
            if not c:
                return n
            n = c[0]

    nodes = [descend(c) for c in kids[""] if tree[c] >= 0.03 * T]
    while len(nodes) < 8:
        cand = [n for n in nodes if tree[n] >= 0.22 * T and len([k for k in kids[n] if tree[k] >= 0.03 * T]) >= 2]
        if not cand:
            break
        n = max(cand, key=lambda x: tree[x])
        nodes.remove(n)
        nodes += [descend(k) for k in kids[n] if tree[k] >= 0.03 * T]
    nodes.sort(key=lambda x: -tree[x])
    return nodes[:8]


def label(path):
    parts = [p for p in path.strip("/").split("/") if p]
    b = parts[-1]
    if b in GENERIC and len(parts) > 1:
        return parts[-2] + "/" + b
    return b


def build_team(b, variant):
    as_of = b["generated_at"]
    feats = [f for f in b.get("features", []) if f.get("author") and f.get("files")]
    if not feats:
        return None
    pw = collections.defaultdict(float)
    pc = collections.Counter()
    plast = {}
    w = collections.defaultdict(lambda: collections.defaultdict(float))
    file_w = collections.defaultdict(float)
    for f in feats:
        if variant == "solo" and f["author"] != "Atharva Shah":
            continue
        a = f["author"]
        decay = 2 ** (-max(0, days(as_of, f["date"])) / 90)
        files = [x for x in f["files"] if not re.search(r"(^|/)\.[^/]+/", x)] or f["files"]
        n = len(files)
        mass = decay * min(1 + math.log2(n), 4)
        for x in files:
            w[a][x] += mass / n
            file_w[x] += mass / n
        pw[a] += mass
        pc[a] += 1
        plast[a] = max(plast.get(a, ""), f["date"])
    T = sum(file_w.values())
    nodes = frontier(file_w, T)

    def area_of(path):
        best = None
        for n in nodes:
            if path.startswith(n) and (best is None or len(n) > len(best)):
                best = n
        return best

    order = sorted(pw, key=lambda a: -pw[a])
    people = order[:12]
    rest_people = order[12:]
    aw = collections.defaultdict(lambda: collections.defaultdict(float))  # area -> person -> w
    alast = {}
    rest_w = 0.0
    for f in feats:
        if variant == "solo" and f["author"] != "Atharva Shah":
            continue
        for x in f["files"]:
            n = area_of(x)
            if n is None:
                continue
            alast[n] = max(alast.get(n, ""), f["date"])
    for a in order:
        for x, v in w[a].items():
            n = area_of(x)
            if n is None:
                rest_w += v
            else:
                aw[n][a if a in people else "others"] += v
    nodes = [n for n in nodes if sum(aw[n].values()) > 0]
    pid = {a: "p%d" % (i + 1) for i, a in enumerate(people)}
    aid = {n: "a%d" % (i + 1) for i, n in enumerate(nodes)}
    areas = []
