            U = 2 ** (-dn / 45)
            E = min(1, n / 5) * 0.85 if many else 0.6 + 0.2 * bool(ev and ev[0].get("pr"))
            J = 1 if jev else 0.6
            m = re.search(r"Add (?:them|it) to (\S+?\.(?:mdx?|rst|txt|adoc))", c.get("action", ""))
            area = re.search(r"`([^`]+)`", c["title"])
            if many and area:
                title = ("Add the new %s changes to %s" % (area.group(1), m.group(1).split("/")[-1])) if m else "Write a page for %s" % area.group(1)
                eff = ("M" if n <= 6 else "L") if m else ("L" if n >= 8 else "M")
                ew = "An existing page gets %d changes" % n if m else "A new page for %d changes" % n
                rat = "%d user-facing %s changes shipped since %s, newest %s on %s, and Jev found no docs page that explains them." % (n, area.group(1), nice(min(e["date"] for e in ev)), ev[0]["sha"], nice(newest))
            else:
                subj = re.sub(r"^\w+(\([^)]*\))?!?:\s*", "", ev[0]["subject"]) if ev else title
                title = "Document: " + subj[:1].upper() + subj[1:]
                eff = "S"
                ew = "One section on an existing page"
                rat = '%s shipped "%s" on %s%s, and Jev read the closest page and found it does not explain it.' % (ev[0]["sha"], ev[0]["subject"][:80], nice(newest), " in #" + ev[0]["pr"] if ev[0].get("pr") else "") if ev else c["why"]
            why_now = "Shipped " + ago(dn)
        elif k == "refresh":
            path = re.sub(r"^Refresh\s+", "", c["title"]).strip()
            p = pages.get(path, {})
            rs = p.get("relevant_since", n)
            entry = 1 if re.search(r"readme|index|quickstart|getting[-_]started|install|introduction|overview", path, re.I) or path.count("/") <= 1 else 0
            I = 0.45 + 0.25 * entry + 0.3 * min(1, rs / 20)
            U = 0.5 * min(1, p.get("age_days", 0) / 730) + 0.5 * 2 ** (-dn / 90)
            E = min(1, rs / 5)
            J = 1 if p.get("judge") == "jev" and p.get("status") == "stale" else 0.6
            eff = "S" if rs <= 3 else "M" if rs <= 10 else "L"
            if p.get("ancient") and eff != "L":
                eff = {"S": "M", "M": "L"}[eff]
            ew = "%d commits to read against the page%s" % (rs, ", and the page is very old" if p.get("ancient") else "")
            title = "Update " + (p.get("title") or path.split("/")[-1])
            rat = "Last edited %s. Since then %d commits changed code on its topic, newest %s on %s, and %s" % (
                nice(p["last_touched"]) if p.get("last_touched") else "before the history starts", rs, ev[0]["sha"] if ev else "?", nice(newest) if newest else "?",
                "Jev expects the page is now wrong." if p.get("judge") == "jev" else "Jev did not read it.")
            why_now = "Code moved %d days ago under a page last edited %d days ago" % (dn, p.get("age_days", 0))
        elif k == "release":
            r = b.get("release") or {}
            if not r.get("commits"):
                continue
            I = 0.5 + 0.15
            U = 2 ** (-days(as_of, r["date"]) / 30)
            E = min(1, r["commits"] / 10)
            J = 0.6
            eff, ew = "S", "The draft is ready to paste"
            title = "Publish the %s release notes" % r["name"]
            rat = "%d commits landed between %s and %s (%s)." % (r["commits"], r.get("previous") or "the first commit", r["name"], nice(r["date"]))
            why_now = "%s shipped %s" % (r["name"], ago(days(as_of, r["date"])))
        elif k == "announce":
            I, U, E, J = 0.25, 2 ** (-dn / 21), 0.5 + 0.2 * bool(ev and ev[0].get("pr")), 0.4
            eff, ew = "S", "One post"
            subj = re.sub(r"^Feature this:\s*", "", c["title"]).replace("`", "")
            title = "Announce: " + subj
            rat = c["why"]
            why_now = "Shipped " + ago(dn)
        else:
            I, U, E, J = 0.4, 0.3, 0.3, 0.5
            eff, ew = "S", "One doc-test run"
            title = "Prove the quickstart still runs"
            rat = c["why"]
            why_now = "A text audit cannot prove a run"
        ease = {"S": 1, "M": 0.6, "L": 0.3}[eff]
        parts = {"impact": round(min(1, I), 2), "urgency": round(U, 2), "evidence": round(min(1, E), 2), "judged": J, "ease": ease}
        score = round(100 * (0.3 * parts["impact"] + 0.25 * U + 0.2 * parts["evidence"] + 0.15 * J + 0.1 * ease))
        it = {"rank": 0, "kind": k, "title": title, "path": path, "area": None, "rationale": rat, "why_now": why_now,
              "score": score, "parts": parts, "effort": eff, "effort_why": ew, "judge": "jev" if jev else "text",
              "action": c.get("action", ""), "count": n, "evidence": ev[:5], "owner": None, "runner_up": None,
              "balanced": False, "fallback": None, "_newest": newest or ""}
        # owner from authors of the evidence commits that the board knows
        if ctx and variant != "disabled":
            auth = collections.Counter(feats[e["sha"]]["author"] for e in ev if e["sha"] in feats)
            files = [x for e in ev if e["sha"] in feats for x in feats[e["sha"]]["files"]]
            if files:
                a = ctx["area_of"](files[0])
                it["area"] = ctx["aid"].get(a)
            if variant == "solo" and k in ("refresh", "quickstart", "release"):
                auth = collections.Counter({"Atharva Shah": 1})
            ranked = [a for a, _ in auth.most_common() if a in ctx["pid"] or a in ctx["order"]]
            it["_cands"] = ranked
            it["_auth"] = auth
        items.append(it)
    items.sort(key=lambda x: (-x["score"], x["_newest"] and -d(x["_newest"]).toordinal(), x["title"]))
    # kind caps in top 10
    caps = {"refresh": 5, "document": 5, "announce": 2, "release": 1, "quickstart": 1}
    top, over, cnt = [], [], collections.Counter()
    for it in items:
        if len(top) < 10 and cnt[it["kind"]] < caps[it["kind"]]:
            top.append(it)
            cnt[it["kind"]] += 1
        else:
            over.append(it)
    items = (top + over)[:30]
    # owners with load balance
    picks = collections.Counter()
    extra = []
    people = team["people"] if team and "people" in team else []
    name2id = {p["name"]: p["id"] for p in people}
    elig = set(a for it in items[:10] for a in it.get("_cands", []))
    cap = max(2, math.ceil(10 / max(1, len(elig))) + 1) if len(elig) > 1 else 99
    for i, it in enumerate(items):
        cands = it.pop("_cands", [])
        auth = it.pop("_auth", collections.Counter())
        it.pop("_newest", None)
        it["rank"] = i + 1
        if not cands:
            if team and "people" in team and variant != "disabled":
                last = it["evidence"][0] if it["evidence"] else None
                it["fallback"] = ("Last touched on %s by someone outside the top contributors" % nice(last["date"])) if last else "No one touched these files in the last year"
            continue

        def idfor(a):
            if a not in name2id and len(people) < 16:
                pid = "p%d" % (len(people) + 1)
                people.append({"id": pid, "name": a, "login": login_of(a), "gh": None, "ini": ini(a), "commits": auth[a], "share": 0.01,
                               "last": it["evidence"][0]["date"], "top": None, "top_share": 0})
                name2id[a] = pid
            return name2id.get(a)
        pick = cands[0]
        if i < 10 and picks[pick] >= cap and len(cands) > 1:
            pick = cands[1]
            it["balanced"] = True
        if i < 10:
            picks[pick] += 1
        n = sum(auth.values())
        k = auth[pick]
        pr = next((e.get("pr") for e in it["evidence"] if e.get("pr")), None)
        if variant == "solo" and it["kind"] in ("refresh", "quickstart", "release"):
            why = "%s made every commit in the last 12 months" % pick
        elif n == 1 and pr:
            why = "%s shipped it in #%s" % (pick, pr)
        else:
            why = "%s wrote %d of the %d changes behind it" % (pick, k, n)
        pid = idfor(pick)
        if pid:
            it["owner"] = {"p": pid, "why": why}
        other = [a for a in cands if a != pick]
        if other:
            rid = idfor(other[0])
            if rid:
                it["runner_up"] = {"p": rid, "why": "%s wrote %d of the %d changes behind it" % (other[0], auth[other[0]], n)}
    return {"v": 1, "top": 10, "weights": {"impact": 0.30, "urgency": 0.25, "evidence": 0.20, "judged": 0.15, "ease": 0.10}, "items": items}


