var T=null,NX=[],PIN=null,HOV=null,SHOWALL=false,SVG=null,RO=null,DRAWN=false;
function isNum(x){return typeof x==="number"&&isFinite(x)}
function str(x,n){return typeof x==="string"?x.slice(0,n||200):""}
function first(n){return String(n||"").split(/\s+/)[0]}
